// Regenerates src/themes.bundle.css from the theme sources.
//
// The bundle exists for apps that consume pica-ui as plain CSS with no Tailwind
// build — tickets-srv reads it off disk and inlines it as a string. It used to
// be a hand-maintained second copy of every theme block, which is exactly the
// shape of thing that drifts: fix a colour in src/themes/x.css, forget the
// bundle, and the two consumers of the same design system disagree.
//
// It is now a byte-for-byte function of src/themes/*.css.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const SRC = join(import.meta.dirname, '../src')

export function renderBundle() {
  const header =
    '/* pica-ui — themes.bundle.css : every theme as plain CSS [data-theme] blocks + fonts.\n' +
    '   GENERATED by scripts/build-bundle.mjs — do not edit by hand.\n' +
    '\n' +
    '   For non-bundled apps (no Tailwind). Set <html data-theme="x"> + class="dark".\n' +
    '   NOTE: the @import below is relative to THIS FILE. An app that inlines this\n' +
    '   stylesheet as a string must also serve src/fonts/ alongside it, or the faces\n' +
    '   404 and every theme falls back to a system font. */\n' +
    '\n' +
    "@import './fonts/fonts.css';\n"

  const themes = readdirSync(join(SRC, 'themes'))
    .filter((f) => f.endsWith('.css'))
    .sort()
    .map((f) => readFileSync(join(SRC, 'themes', f), 'utf8').trim())

  return header + '\n' + themes.join('\n\n') + '\n'
}

if (process.argv[1]?.endsWith('build-bundle.mjs')) {
  writeFileSync(join(SRC, 'themes.bundle.css'), renderBundle())
  console.log('themes.bundle.css regenerated')
}
